#pragma once

#include <stdint.h>

/**
 * The game's 31 effects as data, generated by tools/fxconv.py with the shaders (build/gen/shaders.cpp): parameters with
 * their defaults and annotations, techniques, passes and the state assignments of each pass. The effect runtime
 * (engine/rendering/vulkan/effect.h) works from these tables instead of D3DX.
 */
namespace nfs::vk
{
/** D3DXPARAMETER_TYPE values. */
enum EffectParameterType : uint8_t
{
    kParamVoid = 0,
    kParamBool = 1,
    kParamInt = 2,
    kParamFloat = 3,
    kParamString = 4,
    kParamTexture = 5,
    kParamTextureCube = 9,
    kParamSampler = 10,
    kParamSamplerCube = 14,
    kParamPixelShader = 15,
    kParamVertexShader = 16,
};

/** D3DXPARAMETER_CLASS values. */
enum EffectParameterClass : uint8_t
{
    kClassScalar = 0,
    kClassVector = 1,
    kClassMatrixRows = 2,
    kClassMatrixColumns = 3,
    kClassObject = 4,
    kClassStruct = 5,
};

struct EffectAnnotation
{
    const char *name;
    EffectParameterType type;
    /** The value's bits for bool, int and float annotations. */
    uint32_t value;
    const char *string;
};

struct EffectParameter
{
    const char *name;
    const char *semantic;
    EffectParameterType type;
    EffectParameterClass cls;
    uint8_t rows;
    uint8_t columns;
    uint16_t elements;
    /** DWORDs of the whole value (numeric parameters); 0 for objects. Matrices are stored row by row. */
    uint16_t valueCount;
    /** First DWORD of the default value in EffectInfo::defaults, and where the value lives in an effect instance. */
    uint16_t valueOffset;
    /** Sampler parameters: their sampler state assignments in EffectInfo::states. */
    uint16_t samplerStateStart;
    uint16_t samplerStateCount;
    uint16_t annotationStart;
    uint16_t annotationCount;
    /** Declared `shared`: one value for every effect of the pool (all the game's effects share one), matched by name
     * and type. */
    bool shared;
};

enum class EffectStateType : uint8_t
{
    Render,
    Sampler,
    Texture,
    VertexShader,
    PixelShader,
    /** SAMPLER[n] = <sampler parameter>: that parameter's sampler states and texture on stage n. */
    SetSampler,
    Stage,
    /** Fixed-function state (transforms, lights, materials, FVF...), which the shader techniques do not use. */
    Other,
};

enum class EffectValueKind : uint8_t
{
    Constant,
    /** The value of parameter `value` (a texture or sampler for Texture and SetSampler). */
    Parameter,
    /** DWORD `offset` of parameter `value`, converted to an integer if the parameter is a float. */
    Element,
};

struct EffectState
{
    EffectStateType type;
    EffectValueKind kind;
    /** Sampler or stage index; kBoundStage in a sampler parameter's states. */
    uint8_t slot;
    uint8_t reserved;
    /** D3DRENDERSTATETYPE, D3DSAMPLERSTATETYPE or D3DTEXTURESTAGESTATETYPE. */
    uint16_t id;
    uint16_t offset;
    /** Constant: the value. Parameter, Element: the parameter index. Shaders: the kShaders index, ~0u for none. */
    uint32_t value;
};

constexpr uint8_t kBoundStage = 0xFF;

struct EffectPass
{
    const char *name;
    uint16_t stateStart;
    uint16_t stateCount;
    int16_t vertexShader;
    int16_t pixelShader;
};

struct EffectTechnique
{
    const char *name;
    uint16_t passStart;
    uint16_t passCount;
    uint16_t annotationStart;
    uint16_t annotationCount;
};

struct EffectInfo
{
    /** The resource the game loads it from, e.g. IDI_WORLD_FX. */
    const char *resource;
    const EffectParameter *parameters;
    uint16_t parameterCount;
    uint16_t techniqueCount;
    const EffectTechnique *techniques;
    const EffectPass *passes;
    const EffectState *states;
    const EffectAnnotation *annotations;
    const uint32_t *defaults;
    /** DWORDs of all numeric parameter values together. */
    uint32_t valueCount;
};

extern const EffectInfo kEffects[];
extern const uint32_t kEffectCount;
} // namespace nfs::vk
